# Test the regex on actual filenames from the debug output
test_files = [
    'Chapter_01_The-Artemis-Accord.md',
    'Chapter_02_First-Footsteps.md', 
    'Chapter_36_Critical-Systems-Failure.md'
]

pattern = r'Chapter_(\d+)_(.+)\.md'
print(f"Testing pattern: {pattern}")

for filename in test_files:
    match = re.match(pattern, filename)
    if match:
        num = match.group(1)
        title = match.group(2)
        print(f"✓ {filename} -> num={num}, title='{title}'")
    else:
        print(f"✗ {filename} -> NO MATCH")

# Let's also try a simpler approach
print("\n--- Trying split approach ---")
for filename in test_files:
    if filename.startswith('Chapter_') and filename.endswith('.md'):
        # Remove prefix and suffix
        middle = filename[9:-3]  # Remove 'Chapter_' and '.md'
        # Split on first underscore only
        parts = middle.split('_', 1)
        if len(parts) == 2:
            num, title = parts
            print(f"✓ {filename} -> num='{num}', title='{title}'")
        else:
            print(f"✗ {filename} -> could not split '{middle}'")
    else:
        print(f"✗ {filename} -> wrong format")"}
